// --- Mapa de areas ISA-95 por equipo -------------------------------------
const AREAS = { EQ01: 'CAPT', EQ02: 'FILT', EQ03: 'REAC' };
const EMPRESA = 'AQM';
const PLANTA = 'PTEF';

const d = msg.payload;
if (!d || d.value === undefined || !d.equipo) {
    node.warn('Payload invalido: ' + JSON.stringify(d));
    return null;
}

// Variable: del topic (AQM/PTEF/EQ01/CAUDAL) o del propio payload.
const partesTopic = String(msg.topic || '').split('/');
const variable = partesTopic[3] || (d.tag ? String(d.tag).split('-').pop() : 'NA');
const equipo = d.equipo;
const area = AREAS[equipo] || 'NA';
const tag = d.tag || [EMPRESA, PLANTA, area, equipo, variable].join('-');
const unit = d.unit || '';
const quality = (d.quality === undefined) ? 2 : parseInt(d.quality, 10);
const tsMs = d.ts || Date.now();

// --- Firma: hash corto (djb2) del payload original para trazabilidad -------
function djb2(str) {
    let h = 5381;
    for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
    return h.toString(16).padStart(8, '0');
}
const firma = djb2(JSON.stringify(d));

// --- Escape de valores para tags ILP (coma, espacio, igual) ---------------
function esc(v) {
    return String(v).replace(/([,= ])/g, '\\$1');
}

// --- Construccion de la linea ILP ---------------------------------------
// measurement,tag_set field_set timestamp
const tagSet = [
    'planta=' + esc(PLANTA),
    'area=' + esc(area),
    'equipo=' + esc(equipo),
    'tag=' + esc(tag),
    'variable=' + esc(variable),
    'unit=' + esc(unit || 'NA'),
    'firma=' + esc(firma)
].join(',');

const fieldSet = 'value=' + Number(d.value) + ',quality=' + quality + 'i';
const linea = 'raw_variables,' + tagSet + ' ' + fieldSet + ' ' + tsMs;

msg.payload = linea;
msg.headers = {
    'Content-Type': 'text/plain; charset=utf-8'
};
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;

msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/write?precision=ms';
return msg;

// QuestDB responde 204 No Content cuando la insercion es correcta.
if (msg.statusCode && (msg.statusCode < 200 || msg.statusCode >= 300)) {
    node.error('QuestDB /write status ' + msg.statusCode + ': ' + msg.payload, msg);
    return [null, msg];
}
return [msg, null];
